const afterBalance = reportedKey === effect.balanceKey ? primary.newBalance : primary.newBalance;

// Re-read the reported leg when it is not the primary one: `newBalance`
// belongs to the primary leg only.
const finalReported =
  reportedKey === effect.balanceKey
    ? primary.newBalance
    : (await prisma.inventoryBalance.findFirst({
        where: { key: reportedKey, waterType: input.waterType },
        select: { quantity: true },
      }))?.quantity ?? 0;

reps.newStr:
// `newBalance` belongs to the primary leg only, so when the notification
// reports the other leg (the anbar), that leg is read back after the commit.
const finalReported =
  reportedKey === effect.balanceKey
    ? primary.newBalance
    : (await prisma.inventoryBalance.findFirst({
        where: { key: reportedKey, waterType: input.waterType },
        select: { quantity: true },
      }))?.quantity ?? 0;
